// Test_AutomationAccountsSchedule_Spec_WhenPropertiesConverted_RoundTripsWithoutLoss tests if a specific instance of AutomationAccountsSchedule_Spec can be assigned to storage and back losslessly
func Test_AutomationAccountsSchedule_Spec_WhenPropertiesConverted_RoundTripsWithoutLoss(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	rapid.Check(t, func(t *rapid.T) {
		subject := AutomationAccountsSchedule_SpecGenerator().Draw(t, "subject")
		// Copy subject to make sure assignment doesn't modify it
		copied := subject.DeepCopy()

		// Use AssignPropertiesTo() for the first stage of conversion
		var other storage.AutomationAccountsSchedule_Spec
		err := copied.AssignProperties_To_AutomationAccountsSchedule_Spec(&other)
		if err != nil {
			t.Fatal("AssignPropertiesTo: " + err.Error())
		}

		// Use AssignPropertiesFrom() to convert back to our original type
		var actual AutomationAccountsSchedule_Spec
		err = actual.AssignProperties_From_AutomationAccountsSchedule_Spec(&other)
		if err != nil {
			t.Fatal("AssignPropertiesFrom: " + err.Error())
		}

		// Check for a match
		match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
		if !match {
			actualFmt := pretty.Sprint(actual)
			subjectFmt := pretty.Sprint(subject)
			result := diff.Diff(subjectFmt, actualFmt)
			t.Error(result)
		}
	})
}

